const items: Listing[] = [];
let key = cursor;
do {
  const page = await ddb.send(new QueryCommand({
    TableName: "listings",
    KeyConditionExpression: "pk = :e",
    FilterExpression: "#s = :avail",
    ExpressionAttributeNames: { "#s": "state" },
    ExpressionAttributeValues: { ":e": `EVENT#${eventId}`, ":avail": "AVAILABLE" },
    Limit: 50,
    ExclusiveStartKey: key,
  }));
  items.push(...(page.Items as Listing[]));
  key = page.LastEvaluatedKey;
} while (items.length < 20 && key);
return { items: items.slice(0, 20), next: key };

const ddb = DynamoDBDocumentClient.from(new DynamoDBClient({}));

export async function saveIntake(form: IntakeForm) {
  await ddb.send(new PutCommand({
    TableName: "intake",
    Item: {
      pk: `PATIENT#${form.patientId}`,
      sk: `INTAKE#${form.submittedAt}`,
      reason: form.reason,
      referralCode: form.referralCode, // optional
    },
  }));
}
